// rna.hpp - RNA secondary structure: pushdown automaton, Nussinov (CFG-style DP), dot-bracket checking
//
// Regular languages cannot express base pairing: a stem x . loop . revcomp(x) needs unbounded memory of x.
// A pushdown automaton (finite control + stack) can: push the expected partner of each stem base, skip the
// loop, then pop while reading the 3' side.  Formally the hairpin language is generated by
//   S -> a S u | c S g | g S c | u S a | g S u | u S g | loop
#pragma once
#include <functional>
#include <map>
#include <set>
#include "common.hpp"

namespace bio {

inline bool canPair(char a, char b, bool wobble) {
    a = (char)std::toupper((unsigned char)a);
    b = (char)std::toupper((unsigned char)b);
    if ((a == 'A' && b == 'U') || (a == 'U' && b == 'A')) return true;
    if ((a == 'G' && b == 'C') || (a == 'C' && b == 'G')) return true;
    if (wobble && ((a == 'G' && b == 'U') || (a == 'U' && b == 'G'))) return true;
    return false;
}

// Non-deterministic PDA. Transition: in state `from`, optionally reading `in` (0 = epsilon) with `top` on
// the stack, move to `to`, replacing `top` by `push` (written bottom-to-top). '$' is the bottom marker.
// Acceptance: final state reached with only '$' on the stack (acceptance by final state + empty stack).
struct Pda {
    struct Tr { char in; char top; int to; std::string push; };
    std::vector<std::vector<Tr>> out;
    std::vector<char> fin;
    int start = 0;

    int addState(bool final_ = false) { out.emplace_back(); fin.push_back(final_); return (int)out.size() - 1; }
    void add(int from, char in, char top, int to, const std::string& push) { out[from].push_back({in, top, to, push}); }
    size_t numStates() const { return out.size(); }
    size_t numTransitions() const { size_t n = 0; for (auto& v : out) n += v.size(); return n; }

    // All lengths L such that w[from, from+L) is accepted (exhaustive search over configurations).
    std::set<size_t> acceptingPrefixes(const std::string& w, size_t from) const {
        std::set<size_t> res;
        std::string stack = "$";
        dfs(start, from, from, w, stack, res);
        return res;
    }

private:
    void dfs(int q, size_t pos, size_t from, const std::string& w, std::string& stack, std::set<size_t>& res) const {
        if (fin[q] && stack.size() == 1) res.insert(pos - from);
        char top = stack.back();
        for (const Tr& t : out[q]) {
            if (t.top != top) continue;
            if (t.in && !(pos < w.size() && w[pos] == t.in)) continue;
            stack.pop_back();
            stack += t.push;
            dfs(t.to, pos + (t.in ? 1 : 0), from, w, stack, res);
            stack.resize(stack.size() - t.push.size());
            stack.push_back(top);
        }
    }
};

struct HairpinParams {
    int stemMin = 4, stemMax = 8, loopMin = 3, loopMax = 8;
    bool wobble = true;
};

// Build the PDA for  { x . l . y : |x|=|y|=n in [stemMin,stemMax], |l| in [loopMin,loopMax], y pairs with x }.
// Stem/loop counters are encoded in the finite control (bounded), the stem content lives on the stack.
inline Pda buildHairpinPda(const HairpinParams& p) {
    Pda m;
    const std::string B = "ACGU", tops = "$ACGU";
    auto partners = [&](char a) -> std::string {
        switch (a) {
            case 'A': return "U";
            case 'C': return "G";
            case 'G': return p.wobble ? "CU" : "C";
            default:  return p.wobble ? "AG" : "A";
        }
    };
    std::vector<int> S(p.stemMax + 1), L(p.loopMax + 1);
    for (auto& x : S) x = m.addState();
    for (auto& x : L) x = m.addState();
    int P = m.addState(), F = m.addState(true);
    m.start = S[0];
    for (int k = 0; k <= p.stemMax; ++k) {
        for (char X : tops) {
            if (k < p.stemMax)
                for (char a : B)
                    for (char y : partners(a)) m.add(S[k], a, X, S[k + 1], std::string(1, X) + y);
            if (k >= p.stemMin) m.add(S[k], 0, X, L[0], std::string(1, X));
        }
    }
    for (int j = 0; j <= p.loopMax; ++j) {
        for (char X : tops) {
            if (j < p.loopMax) for (char a : B) m.add(L[j], a, X, L[j + 1], std::string(1, X));
            if (j >= p.loopMin) m.add(L[j], 0, X, P, std::string(1, X));
        }
    }
    for (char b : B) m.add(P, b, b, P, "");
    m.add(P, 0, '$', F, "$");
    return m;
}

struct Hairpin {
    size_t start, end;
    int stem, loop, score;
    std::string structure;
};

inline std::vector<Hairpin> findHairpins(const std::string& rna, const HairpinParams& p) {
    Pda pda = buildHairpinPda(p);
    std::vector<Hairpin> best;
    std::map<std::pair<size_t, size_t>, size_t> byLoop;  // loop region -> index in best
    for (size_t i = 0; i < rna.size(); ++i) {
        for (size_t len : pda.acceptingPrefixes(rna, i)) {
            // recover the parse: largest stem that explains this length
            for (int n = std::min<int>(p.stemMax, (int)len / 2); n >= p.stemMin; --n) {
                int loop = (int)len - 2 * n;
                if (loop < p.loopMin || loop > p.loopMax) continue;
                bool ok = true;
                int score = 0;
                for (int t = 0; t < n && ok; ++t) {
                    char a = rna[i + t], b = rna[i + len - 1 - t];
                    ok = canPair(a, b, p.wobble);
                    if (ok) score += (a == 'G' && b == 'C') || (a == 'C' && b == 'G') ? 3 : ((a == 'G' || a == 'U') && (b == 'U' || b == 'G') && a != b) ? 1 : 2;
                }
                if (!ok) continue;
                Hairpin h{i, i + len, n, loop, score,
                          std::string(n, '(') + std::string(loop, '.') + std::string(n, ')')};
                auto key = std::make_pair(i + n, i + len - n);
                auto it = byLoop.find(key);
                if (it == byLoop.end()) { byLoop[key] = best.size(); best.push_back(h); }
                else if (best[it->second].stem < n) best[it->second] = h;
                break;
            }
        }
    }
    std::sort(best.begin(), best.end(), [](const Hairpin& a, const Hairpin& b) { return a.start < b.start; });
    return best;
}

// Nussinov maximum base-pair DP. This is CYK-style parsing of the ambiguous RNA grammar
//   S -> S S | a S u | ... | a S | S a | eps    maximising the number of paired symbols.  O(n^3) time, O(n^2) space.
inline std::string nussinov(const std::string& rna, int& pairs, bool wobble = true, int minLoop = 3) {
    int n = (int)rna.size();
    std::vector<std::vector<int>> dp(n + 2, std::vector<int>(n + 2, 0));
    auto D = [&](int i, int j) { return i >= j ? 0 : dp[i][j]; };
    auto pr = [&](int i, int j) { return j - i > minLoop && canPair(rna[i], rna[j], wobble); };
    for (int len = 1; len < n; ++len)
        for (int i = 0; i + len < n; ++i) {
            int j = i + len;
            int b = std::max(D(i + 1, j), D(i, j - 1));
            if (pr(i, j)) b = std::max(b, D(i + 1, j - 1) + 1);
            for (int k = i + 1; k < j; ++k) b = std::max(b, D(i, k) + D(k + 1, j));
            dp[i][j] = b;
        }
    std::string db(n, '.');
    std::function<void(int, int)> tb = [&](int i, int j) {
        if (i >= j) return;
        int v = D(i, j);
        if (v == D(i + 1, j)) { tb(i + 1, j); return; }
        if (v == D(i, j - 1)) { tb(i, j - 1); return; }
        if (pr(i, j) && v == D(i + 1, j - 1) + 1) { db[i] = '('; db[j] = ')'; tb(i + 1, j - 1); return; }
        for (int k = i + 1; k < j; ++k)
            if (v == D(i, k) + D(k + 1, j)) { tb(i, k); tb(k + 1, j); return; }
    };
    tb(0, n - 1);
    pairs = n > 1 ? D(0, n - 1) : 0;
    return db;
}

struct DbResult { bool ok = true; bool pseudoknot = false; int pairs = 0; std::string msg; };

// Dot-bracket validation = running a (multi-)stack PDA. One stack per bracket type: nested structures
// need only the '(' stack; pseudoknots ([] {} <>) need several interleaved stacks, which is beyond a single
// PDA, i.e. beyond context-free languages.
inline DbResult validateDotBracket(const std::string& rna, const std::string& db, bool wobble = true, int minLoop = 3) {
    DbResult r;
    if (rna.size() != db.size()) { r.ok = false; r.msg = "length mismatch between sequence and structure"; return r; }
    const std::string open = "([{<", close = ")]}>";
    std::vector<std::vector<size_t>> st(4);
    for (size_t i = 0; i < db.size(); ++i) {
        char c = db[i];
        size_t o = open.find(c), cl = close.find(c);
        if (c == '.') continue;
        if (o != std::string::npos) { st[o].push_back(i); if (o > 0) r.pseudoknot = true; }
        else if (cl != std::string::npos) {
            if (st[cl].empty()) { r.ok = false; r.msg = "unmatched '" + std::string(1, c) + "' at " + std::to_string(i + 1); return r; }
            size_t j = st[cl].back(); st[cl].pop_back();
            if ((int)(i - j) - 1 < minLoop) { r.ok = false; r.msg = "hairpin loop shorter than " + std::to_string(minLoop) + " between " + std::to_string(j + 1) + " and " + std::to_string(i + 1); return r; }
            if (!canPair(rna[j], rna[i], wobble)) { r.ok = false; r.msg = std::string("non-canonical pair ") + rna[j] + "-" + rna[i] + " at " + std::to_string(j + 1) + "," + std::to_string(i + 1); return r; }
            ++r.pairs;
        } else { r.ok = false; r.msg = std::string("illegal character '") + c + "'"; return r; }
    }
    for (auto& s : st) if (!s.empty()) { r.ok = false; r.msg = "unclosed bracket at " + std::to_string(s.back() + 1); return r; }
    return r;
}

}  // namespace bio
